/// How many there are.
pub const NESTED_COUNT: usize = 9160;

/// Implements part of the nested-question family.
///
/// What one routine does, if it is one of these.
#[must_use]
pub fn routine_at(routine: u32) -> Option<&'static Routine> {
    NESTED
        .binary_search_by_key(&routine, |held| held.routine)
        .ok()
        .map(|at| &NESTED[at])
}

/// Implements part of the nested-question family.
///
/// How deep one routine goes. Zero means nothing sits inside anything.
#[must_use]
pub fn deepest(held: &Routine) -> u8 {
    held.steps.iter().map(|step| step.depth).max().unwrap_or(0)
}

/// Implements part of the nested-question family.
///
/// Whether a routine is a constructor.
///
/// It is if it both makes an instance and does the finishing step. The two are
/// never in the same step, because one flag decides both.
#[must_use]
pub fn is_a_constructor(held: &Routine) -> bool {
    held.steps
        .iter()
        .any(|step| step.calls.contains(&MAKES_AN_INSTANCE))
        && held
            .steps
            .iter()
            .any(|step| step.calls.contains(&AFTER_IT_IS_MADE))
}

/// Implements part of the nested-question family.
///
/// Every routine that is a constructor.
#[must_use]
pub fn constructors() -> Vec<&'static Routine> {
    NESTED
        .iter()
        .filter(|held| is_a_constructor(held))
        .collect()
}

/// Implements part of the nested-question family.
///
/// Whether the two halves of a constructor sit in different steps.
#[must_use]
pub fn halves_are_apart(held: &Routine) -> bool {
    let makes = held
        .steps
        .iter()
        .position(|step| step.calls.contains(&MAKES_AN_INSTANCE));
    let finishes = held
        .steps
        .iter()
        .position(|step| step.calls.contains(&AFTER_IT_IS_MADE));
    match (makes, finishes) {
        (Some(one), Some(other)) => one != other,
        _ => false,
    }
}

/// Implements part of the nested-question family.
///
/// The step that encloses the one at `at`, if any.
///
/// It is the nearest step before it that sits one level shallower.
#[must_use]
pub fn encloser_of(held: &Routine, at: usize) -> Option<&'static Step> {
    let depth = held.steps.get(at)?.depth;
    if depth == 0 {
        return None;
    }
    held.steps[..at]
        .iter()
        .rposition(|step| step.depth == depth - 1)
        .map(|found| &held.steps[found])
}

/// Implements part of the nested-question family.
///
/// How many calls the average step at one depth makes.
///
/// It falls away below the top level: the work of these routines sits in the
/// body, and what the nesting does is narrow a condition.
#[must_use]
pub fn calls_at_depth(depth: u8) -> f64 {
    let steps: Vec<&Step> = NESTED
        .iter()
        .flat_map(|held| held.steps.iter())
        .filter(|step| step.depth == depth)
        .collect();
    if steps.is_empty() {
        return 0.0;
    }
    let calls: usize = steps.iter().map(|step| step.calls.len()).sum();
    #[expect(
        clippy::cast_precision_loss,
        reason = "counts of a few tens of thousands, well inside what a double holds exactly"
    )]
    {
        calls as f64 / steps.len() as f64
    }
}

/// Implements part of the nested-question family.
///
/// What share of these routines have something inside something else.
#[must_use]
pub fn share_nesting() -> f64 {
    let nested = NESTED.iter().filter(|held| deepest(held) > 0).count();
    #[expect(
        clippy::cast_precision_loss,
        reason = "counts of a few thousand, well inside what a double holds exactly"
    )]
    {
        nested as f64 / NESTED.len() as f64
    }
}

/// Implements part of the nested-question family.
///
/// The questions a routine asks only because the ones before them failed.
///
/// Two or more in a row is a chain: the same value tried against one constant
/// after another, which is a decision over cases written out by hand.
#[must_use]
pub fn asked_only_otherwise(held: &Routine) -> Vec<&'static Step> {
    held.steps
        .iter()
        .filter(|step| matches!(step.does, Does::AskingOtherwise(_)))
        .collect()
}

/// Implements part of the nested-question family.
///
/// Every routine that tries a value against one constant after another.
#[must_use]
pub fn chains_of_cases() -> Vec<&'static Routine> {
    NESTED
        .iter()
        .filter(|held| asked_only_otherwise(held).len() >= 2)
        .collect()
}

/// Implements part of the nested-question family.
///
/// What the steps are, commonest first.
#[must_use]
pub fn steps_by_kind() -> Vec<(Does, usize)> {
    let mut counted: Vec<(Does, usize)> = Vec::new();
    for step in NESTED.iter().flat_map(|held| held.steps.iter()) {
        match counted.iter_mut().find(|(does, _)| *does == step.does) {
            Some((_, seen)) => *seen += 1,
            None => counted.push((step.does, 1)),
        }
    }
    counted.sort_by_key(|(_, seen)| std::cmp::Reverse(*seen));
    counted
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_count_is_what_the_table_holds() {
        assert_eq!(NESTED.len(), NESTED_COUNT);
    }

    #[test]
    fn the_table_is_sorted_so_it_can_be_searched() {
        assert!(
            NESTED
                .windows(2)
                .all(|pair| pair[0].routine < pair[1].routine)
        );
    }

    #[test]
    fn a_routine_can_be_found_by_its_address() {
        let known = NESTED[0].routine;

        assert!(routine_at(known).is_some());
        assert!(routine_at(0).is_none());
    }

    #[test]
    fn every_recorded_call_is_a_function_that_was_recovered() {
        // A thunk the decompiler could not resolve is written FUN_ too, but its
        // address is not a function of this program at all. Those are counted
        // by `through_a_thunk` instead of being written down as calls.
        for held in &NESTED {
            for call in held.steps.iter().flat_map(|step| step.calls.iter()) {
                assert!(
                    (FIRST_RECOVERED..=LAST_RECOVERED).contains(call),
                    "{call:#010X} in {:#010X}",
                    held.routine
                );
            }
        }
    }

    #[test]
    fn some_routines_call_through_a_thunk_as_well() {
        let thunked = NESTED.iter().filter(|held| held.through_a_thunk).count();

        assert!(thunked > 0);
        assert!(thunked < NESTED.len() / 2);
    }

    #[test]
    fn the_depths_of_a_routine_only_ever_step_down_by_one() {
        for held in &NESTED {
            let mut last = 0_u8;
            for step in held.steps {
                assert!(step.depth <= last + 1, "{:#010X}", held.routine);
                last = step.depth;
            }
        }
    }

    #[test]
    fn the_first_step_of_a_routine_is_at_the_top() {
        for held in &NESTED {
            assert_eq!(held.steps[0].depth, 0, "{:#010X}", held.routine);
        }
    }

    #[test]
    fn a_step_at_the_top_encloses_nothing() {
        for held in NESTED.iter().take(400) {
            assert!(encloser_of(held, 0).is_none());
        }
    }

    #[test]
    fn a_nested_step_is_enclosed_by_one_a_level_shallower() {
        for held in NESTED.iter().take(400) {
            for (at, step) in held.steps.iter().enumerate() {
                if step.depth > 0 {
                    let outer = encloser_of(held, at).expect("an encloser");
                    assert_eq!(outer.depth, step.depth - 1, "{:#010X}", held.routine);
                }
            }
        }
    }

    #[test]
    fn a_step_that_runs_whatever_happens_is_never_a_question() {
        for held in &NESTED {
            for step in held.steps {
                if step.does == Does::Straightaway {
                    assert!(!matches!(step.does, Does::Asking(_)));
                }
            }
        }
    }

    #[test]
    fn most_of_them_have_nothing_inside_anything() {
        let flat = NESTED.iter().filter(|held| deepest(held) == 0).count();

        assert!(flat * 2 > NESTED.len(), "{flat} of {}", NESTED.len());
    }

    #[test]
    fn and_going_two_deep_is_rare() {
        let deep = NESTED.iter().filter(|held| deepest(held) >= 2).count();

        assert!(deep * 10 < NESTED.len(), "{deep} of {}", NESTED.len());
    }

    #[test]
    fn the_work_sits_at_the_top_and_thins_below_it() {
        // A step at the outermost level calls more than one thing on average; a
        // step inside a branch calls well under one. The nesting narrows a
        // condition rather than carrying the routine.
        let top = calls_at_depth(0);
        let under = calls_at_depth(1);

        assert!(top > 1.0, "{top}");
        assert!(under < top, "{under} against {top}");
    }

    #[test]
    fn a_depth_nothing_reaches_averages_nothing() {
        assert!((calls_at_depth(200) - 0.0).abs() < f64::EPSILON);
    }

    #[test]
    fn many_of_them_are_constructors() {
        let built = constructors().len();

        assert!(built > 500, "{built}");
    }

    #[test]
    fn and_in_every_one_the_two_halves_sit_in_different_steps() {
        // The same thing the top-level sweep found, holding in a population it
        // never looked at: one flag decides whether an instance is made and
        // whether the finishing step is owed, so the two are never together.
        for held in constructors() {
            assert!(halves_are_apart(held), "{:#010X}", held.routine);
        }
    }

    #[test]
    fn a_constructor_makes_its_instance_exactly_once() {
        for held in constructors() {
            let makes = held
                .steps
                .iter()
                .flat_map(|step| step.calls.iter())
                .filter(|call| **call == MAKES_AN_INSTANCE)
                .count();

            assert_eq!(makes, 1, "{:#010X}", held.routine);
        }
    }

    #[test]
    fn some_steps_call_nothing_and_that_is_the_point_of_recording_them() {
        let silent = NESTED
            .iter()
            .flat_map(|held| held.steps.iter())
            .filter(|step| step.calls.is_empty())
            .count();

        assert!(silent > 0);
    }

    #[test]
    fn but_every_routine_calls_something_somewhere() {
        for held in &NESTED {
            assert!(
                held.steps.iter().any(|step| !step.calls.is_empty()),
                "{:#010X}",
                held.routine
            );
        }
    }

    #[test]
    fn every_routine_has_a_question_or_a_loop_in_it() {
        for held in &NESTED {
            assert!(
                held.steps
                    .iter()
                    .any(|step| step.does != Does::Straightaway),
                "{:#010X}",
                held.routine
            );
        }
    }

    #[test]
    fn the_commonest_step_runs_whatever_happened() {
        assert_eq!(steps_by_kind()[0].0, Does::Straightaway);
    }

    #[test]
    fn a_question_asked_only_otherwise_is_not_the_same_as_a_plain_one() {
        // Being reached at all is part of what the branch means, so the two are
        // kept apart even when the question itself is identical.
        assert_ne!(
            Does::Asking(Asks::IsThatValue),
            Does::AskingOtherwise(Asks::IsThatValue)
        );
    }

    #[test]
    fn some_routines_try_a_value_against_one_constant_after_another() {
        let chains = chains_of_cases();

        assert!(!chains.is_empty());
        for held in chains.iter().take(50) {
            assert!(
                asked_only_otherwise(held).len() >= 2,
                "{:#010X}",
                held.routine
            );
        }
    }

    #[test]
    fn and_that_is_overwhelmingly_a_test_against_a_particular_value() {
        // Which is what the shape is for: a decision over cases, written out by
        // hand rather than as a jump table.
        let mut against_a_value = 0;
        let mut otherwise = 0;
        for step in NESTED.iter().flat_map(|held| held.steps.iter()) {
            match step.does {
                Does::AskingOtherwise(Asks::IsThatValue) => against_a_value += 1,
                Does::AskingOtherwise(_) => otherwise += 1,
                _ => {}
            }
        }

        assert!(
            against_a_value > otherwise,
            "{against_a_value} against {otherwise}"
        );
    }

    #[test]
    fn the_three_run_time_routines_are_the_ones_recovered_earlier() {
        assert_eq!(MAKES_AN_INSTANCE, 0x004119E0);
        assert_eq!(AFTER_IT_IS_MADE, 0x00411A20);
        assert_eq!(TAKES_IT_APART, 0x00411A00);
    }

    #[test]
    fn none_of_these_is_already_spoken_for_by_another_sweep() {
        for held in NESTED.iter().take(300) {
            assert!(crate::question_routines::asking_at(held.routine).is_none());
            assert!(crate::two_way_routines::choice_at(held.routine).is_none());
            assert!(crate::guarded_routines::guarded_at(held.routine).is_none());
            assert!(crate::loop_routines::iterates_at(held.routine).is_none());
        }
    }

    #[test]
    fn every_routine_is_listed_once() {
        let mut routines: Vec<u32> = NESTED.iter().map(|held| held.routine).collect();
        let before = routines.len();
        routines.sort_unstable();
        routines.dedup();

        assert_eq!(routines.len(), before);
    }
}
